/**
 * Site-wide metadata for the colorful personal blog.
 */
export interface SiteMetadata {
  /** Display name of the blog. */
  title: string;
  /** Short description used for SEO and sharing. */
  description: string;
  /** Canonical site URL. */
  url: string;
  /** Blog author or owner name. */
  author: string;
  /** Primary brand color in hex or CSS-compatible format. */
  primaryColor: string;
  /** Secondary brand color in hex or CSS-compatible format. */
  secondaryColor: string;
}

/**
 * A navigation item shown in the blog header or sidebar.
 */
export interface NavigationItem {
  /** Unique item label shown to users. */
  label: string;
  /** Target path or URL. */
  href: string;
  /** Whether the navigation item is currently active. */
  active?: boolean;
  /** Optional icon name or identifier. */
  icon?: string;
}

/**
 * Hero section content presented at the top of the landing page.
 */
export interface HeroContent {
  /** Main headline. */
  headline: string;
  /** Supporting subtitle. */
  subtitle: string;
  /** Short introduction paragraph. */
  description: string;
  /** Primary call-to-action label. */
  primaryActionLabel: string;
  /** Primary call-to-action link. */
  primaryActionHref: string;
  /** Optional secondary action label. */
  secondaryActionLabel?: string;
  /** Optional secondary action link. */
  secondaryActionHref?: string;
  /** Decorative background gradient or image reference. */
  backgroundStyle?: string;
}

/**
 * A tag used to categorize blog posts.
 */
export interface BlogTag {
  /** Tag name displayed to readers. */
  name: string;
  /** Slug used in routes or filtering. */
  slug: string;
  /** Accent color associated with the tag. */
  color?: string;
  /** Number of posts in the tag, if known. */
  count?: number;
}

/**
 * A social profile link displayed in the blog.
 */
export interface SocialLink {
  /** Platform name, such as GitHub or X. */
  platform: string;
  /** Profile URL. */
  href: string;
  /** Icon name or identifier for the platform. */
  icon?: string;
  /** Optional accessible label for the link. */
  label?: string;
}

/**
 * A compact post card used in listings and grids.
 */
export interface PostCard {
  /** Unique post identifier. */
  id: string;
  /** Post title. */
  title: string;
  /** Short excerpt or summary. */
  excerpt: string;
  /** Cover image URL. */
  coverImage: string;
  /** Publication date in ISO format. */
  publishedAt: string;
  /** Estimated reading time, in minutes. */
  readingTimeMinutes: number;
  /** Associated post tags. */
  tags: BlogTag[];
  /** Author name if different from site metadata. */
  author?: string;
  /** Whether the post is featured. */
  featured?: boolean;
  /** Canonical post URL or route. */
  href: string;
}

/**
 * Complete data bundle for rendering the blog UI.
 */
export interface BlogMockData {
  /** Site metadata object. */
  site: SiteMetadata;
  /** Header or sidebar navigation items. */
  navigation: NavigationItem[];
  /** Hero banner content. */
  hero: HeroContent;
  /** Popular tags. */
  tags: BlogTag[];
  /** Social profile links. */
  socialLinks: SocialLink[];
  /** Featured and recent post cards. */
  posts: PostCard[];
}

