/**
 * Returns the featured posts from a list of post cards.
 *
 * @param posts - The list of posts to filter.
 * @returns Featured posts in the same order they appear in the input list.
 */
export function getFeaturedPosts(posts: PostCard[]): PostCard[] {
  return posts.filter((post) => post.featured === true);
}

/**
 * Returns a post card by its identifier.
 *
 * @param posts - The list of posts to search.
 * @param id - The post identifier.
 * @returns The matching post, or undefined if not found.
 */
export function findPostById(posts: PostCard[], id: string): PostCard | undefined {
  return posts.find((post) => post.id === id);
}

