}

/**
 * Footer layout model.
 */
export interface FooterLayout {
  copyrightText: string;
  socialLinks: SocialLink[];
  navigationLabels: string[];
}

function getFeaturedPosts(data: BlogMockData): PostCard[] {
  return data.featuredPosts.filter((post: PostCard) => post.featured === true);
}

function getFilterTags(data: BlogMockData): BlogTag[] {
  const seen: Set<string> = new Set<string>();
  const tags: BlogTag[] = [];

  for (const post of data.featuredPosts.concat(data.recentPosts)) {
    for (const tag of post.tags) {
      if (!seen.has(tag.slug)) {
        seen.add(tag.slug);
        tags.push(tag);
      }
    }
  }

  return tags;
}

/**
 * Build the full main page composition from structured blog content.
 */
export function buildMainPageLayout(data: BlogMockData): MainPageLayout {
  const featuredPosts: PostCard[] = getFeaturedPosts(data);
  const filterTags: BlogTag[] = getFilterTags(data);
  const allPosts: PostCard[] = data.featuredPosts.concat(data.recentPosts);

  return {
    hero: {
      title: data.hero.headline,
      subtitle: data.hero.subtitle,
      description: data.hero.description,
      primaryActionLabel: data.hero.primaryActionLabel,
      primaryActionHref: data.hero.primaryActionHref,
      secondaryActionLabel: data.hero.secondaryActionLabel,
      secondaryActionHref: data.hero.secondaryActionHref,
      backgroundStyle: data.hero.backgroundStyle,
    },
    filters: {
      title: '按标签探索内容',
      allTags: filterTags,
      activeSlug: undefined,
      allPostsLabel: `全部文章 · ${allPosts.length}`,
    },
    featuredPosts: {
      title: '精选文章',
      posts: featuredPosts.length > 0 ? featuredPosts : data.featuredPosts,
      viewAllLabel: '查看全部文章',
      viewAllHref: '/posts',
    },
    about: {
      title: '关于这个博客',
      summary: '用色彩、故事和持续更新的笔记，构建一个充满灵感的数字角落。',
      author: data.site.author,
      siteTitle: data.site.title,
      siteDescription: data.site.description,
    },
    footer: {
      copyrightText: `© ${new Date().getFullYear()} ${data.site.author} · ${data.site.title}`,
      socialLinks: data.socialLinks,
      navigationLabels: data.navigation.map((item: { label: string }) => item.label),
    },
  };
}

import type { SiteMetadata } from './types';

/**
 * A gradient palette used to build vivid blog surfaces and accents.
 */
export interface GradientPalette {
  /** Human-readable palette name. */
  name: string;
  /** CSS linear-gradient value. */
  background: string;
  /** Text color that contrasts with the gradient. */
  textColor: string;
  /** Optional border/outline color suitable for the palette. */
  borderColor: string;
}

/**
 * Supported animation presets for the blog UI.
 */
export type AnimationPreset =
  | 'float'
  | 'glow'
  | 'pulse'
  | 'slideUp'
  | 'slideInLeft'
  | 'slideInRight'
  | 'shimmer'
  | 'bounceGentle';

/**
 * Supported card visual variants.
 */
export type CardVariant =
  | 'glass'
  | 'neon'
  | 'soft'
  | 'outline'
  | 'spotlight';

/**
 * Responsive breakpoint names.
 */
export type Breakpoint = 'sm' | 'md' | 'lg' | 'xl' | '2xl';

/**
 * A responsive style helper result.
 */
export interface ResponsiveLayout {
  /** CSS class name string for the layout container. */
  containerClassName: string;
  /** CSS class name string for the content grid. */
  gridClassName: string;
  /** CSS class name string for spacing. */
  spacingClassName: string;
}

