  shimmer: 'animate-[shimmer_1.8s_linear_infinite]',
  bounceGentle: 'animate-[bounceGentle_1.2s_ease-in-out_infinite]',
};

const CARD_VARIANTS: Record<CardVariant, string> = {
  glass: 'rounded-2xl border border-white/20 bg-white/10 backdrop-blur-xl shadow-xl shadow-black/10',
  neon: 'rounded-2xl border border-fuchsia-400/40 bg-zinc-950/80 shadow-[0_0_30px_rgba(217,70,239,0.28)]',
  soft: 'rounded-2xl border border-slate-200/70 bg-white shadow-lg shadow-slate-200/60',
  outline: 'rounded-2xl border border-current/15 bg-transparent',
  spotlight: 'rounded-3xl border border-white/15 bg-gradient-to-br from-white/15 to-white/5 shadow-2xl shadow-black/10',
};

/**
 * Returns a copy of the built-in gradient palettes.
 *
 * @returns Available vivid gradient palettes.
 */
export function getGradientPalettes(): GradientPalette[] {
  return DEFAULT_GRADIENTS.map((palette) => ({ ...palette }));
}

/**
 * Picks a gradient palette from site metadata, falling back to the first palette.
 *
 * @param metadata - Site metadata containing brand colors.
 * @returns A gradient palette aligned to the site's theme.
 */
export function createBrandGradient(metadata: SiteMetadata): GradientPalette {
  const background = `linear-gradient(135deg, ${metadata.primaryColor} 0%, ${metadata.secondaryColor} 100%)`;
  const textColor = isLightColor(metadata.primaryColor) || isLightColor(metadata.secondaryColor) ? '#111827' : '#ffffff';
  return {
    name: 'brand',
    background,
    textColor,
    borderColor: withAlpha(textColor === '#ffffff' ? '#ffffff' : '#111827', 0.18),
  };
}

/**
 * Gets the Tailwind-compatible animation class for a preset.
 *
 * @param preset - Animation preset name.
 * @returns CSS class string for the animation.
 */
export function getAnimationClass(preset: AnimationPreset): string {
  return ANIMATION_CLASSES[preset];
}

/**
 * Gets the Tailwind-compatible card classes for a variant.
 *
 * @param variant - Card visual variant.
 * @returns CSS class string for the card.
 */
export function getCardVariantClass(variant: CardVariant): string {
  return CARD_VARIANTS[variant];
}

/**
 * Builds responsive layout helper classes for the blog.
 *
 * @param breakpoint - Minimum screen size for the layout.
 * @returns Responsive class names for containers, grids, and spacing.
 */
export function getResponsiveLayout(breakpoint: Breakpoint): ResponsiveLayout {
  const breakpointPrefix = breakpoint === 'sm' ? '' : `${breakpoint}:`;
  return {
    containerClassName: 'mx-auto w-full max-w-7xl px-4 sm:px-6 lg:px-8',
    gridClassName: `${breakpointPrefix}grid ${breakpointPrefix}grid-cols-1 ${breakpoint === 'sm' ? 'grid grid-cols-1' : ''} ${breakpoint === 'lg' ? 'lg:grid-cols-12' : breakpoint === 'md' ? 'md:grid-cols-8' : breakpoint === 'xl' ? 'xl:grid-cols-12' : breakpoint === '2xl' ? '2xl:grid-cols-12' : ''}`.trim(),
    spacingClassName: breakpoint === 'sm' ? 'gap-4' : breakpoint === 'md' ? 'gap-6' : breakpoint === 'lg' ? 'gap-8' : 'gap-10',
  };
}

/**
 * Creates a complete style map that combines gradient, animation, and card helpers.
 *
 * @param metadata - Site metadata for brand-aware styling.
 * @returns A practical style utility bundle for vivid blog UI components.
 */
export function createStyleSystem(metadata: SiteMetadata): {
  brandGradient: GradientPalette;
  palettes: GradientPalette[];
  animations: Record<AnimationPreset, string>;
  cards: Record<CardVariant, string>;
  layout: Record<Breakpoint, ResponsiveLayout>;
} {
  return {
    brandGradient: createBrandGradient(metadata),
    palettes: getGradientPalettes(),
    animations: { ...ANIMATION_CLASSES },
    cards: { ...CARD_VARIANTS },
    layout: {
      sm: getResponsiveLayout('sm'),
      md: getResponsiveLayout('md'),
      lg: getResponsiveLayout('lg'),
      xl: getResponsiveLayout('xl'),
      '2xl': getResponsiveLayout('2xl'),
    },
  };
}

function isLightColor(color: string): boolean {
  const rgb = parseColor(color);
  if (!rgb) {
    return false;
  }
  const [r, g, b] = rgb;
  const luminance = (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255;
  return luminance >= 0.65;
}

function withAlpha(color: string, alpha: number): string {
  const rgb = parseColor(color);
  if (!rgb) {
    return color;
  }
  const [r, g, b] = rgb;
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

function parseColor(color: string): [number, number, number] | null {
  const hex = color.trim();
  if (!hex.startsWith('#')) {
    return null;
  }
  const value = hex.slice(1);
  if (value.length === 3) {
    const r = Number.parseInt(value[0] + value[0], 16);
    const g = Number.parseInt(value[1] + value[1], 16);
    const b = Number.parseInt(value[2] + value[2], 16);
    return [r, g, b];
  }
  if (value.length === 6) {
    const r = Number.parseInt(value.slice(0, 2), 16);
    const g = Number.parseInt(value.slice(2, 4), 16);
    const b = Number.parseInt(value.slice(4, 6), 16);
    return [r, g, b];
  }
  return null;
}
